import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.CWgsre3x.js";const u=JSON.parse('{"title":"Αντίγραφα, ανάκτηση και επιχειρησιακή συνέχεια","description":"","frontmatter":{},"headers":[],"relativePath":"el/getting-started/backup-recovery.md","filePath":"el/getting-started/backup-recovery.md"}'),l={name:"el/getting-started/backup-recovery.md"};function o(s,a,n,c,h,d){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="αντιγραφα-ανακτηση-και-επιχειρησιακη-συνεχεια" tabindex="-1">Αντίγραφα, ανάκτηση και επιχειρησιακή συνέχεια <a class="header-anchor" href="#αντιγραφα-ανακτηση-και-επιχειρησιακη-συνεχεια" aria-label="Permalink to &quot;Αντίγραφα, ανάκτηση και επιχειρησιακή συνέχεια&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Οδηγίες βάσει v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, δικαιώματα και εγκεκριμένο εύρος. Η εκπαίδευση χρησιμοποιεί εγκεκριμένα συνθετικά δεδομένα· δεν εγκρίνεται εμπορική ενεργοποίηση.</p></div><h2 id="συμφωνια-σχεδιου-ανακτησης" tabindex="-1">Συμφωνία σχεδίου ανάκτησης <a class="header-anchor" href="#συμφωνια-σχεδιου-ανακτησης" aria-label="Permalink to &quot;Συμφωνία σχεδίου ανάκτησης&quot;">​</a></h2><p>Οι υπεύθυνοι φιλοξενίας και επιχείρησης συμφωνούν στόχους σημείου και χρόνου ανάκτησης, διατήρηση, κρυπτογράφηση, αντίγραφα εκτός συστήματος και επαφές. Δεν υπονοείται αριθμητικό SLA. Διατηρήστε συμβατά αντίγραφα βάσης, πακέτα, απαραίτητες ρυθμίσεις και περιεχόμενο πελάτη. Προστατεύστε μυστικά και υλικό υπογραφής σε χωριστή εξουσιοδοτημένη διαδικασία.</p><h2 id="πριν-απο-αλλαγες" tabindex="-1">Πριν από αλλαγές <a class="header-anchor" href="#πριν-απο-αλλαγες" aria-label="Permalink to &quot;Πριν από αλλαγές&quot;">​</a></h2><ol><li>Επιβεβαιώστε περιβάλλον, εγκατεστημένη έκδοση, σχήμα βάσης και απαιτήσεις migration.</li><li>Ελέγξτε ταυτότητα, checksum και αναγνωσιμότητα αντιγράφου. Αναγνώσιμο αρχείο δεν αποδεικνύει επαναφορά· εκτελέστε και καταγράψτε απομονωμένη δοκιμή.</li><li>Διατηρήστε περιεχόμενο, domains, τοπικά πρότυπα, διασυνδέσεις και εταιρική πρόσβαση· καθορίστε κριτήρια επαναφοράς ή διορθωτικής αναβάθμισης.</li><li>Λάβετε έγκριση και τεκμηριώστε παράθυρο συντήρησης. Χρησιμοποιήστε μόνο εγκεκριμένη ενημέρωση.</li></ol><h2 id="κατα-τη-διακοπη" tabindex="-1">Κατά τη διακοπή <a class="header-anchor" href="#κατα-τη-διακοπη" aria-label="Permalink to &quot;Κατά τη διακοπή&quot;">​</a></h2><p>Σταματήστε αβέβαιες επαναλήψεις. Διατηρήστε αναφορές κρατήσεων, αναγνωριστικά πληρωμών και χρόνους συμβάντων χωρίς έκθεση διαπιστευτηρίων. Χρησιμοποιήστε συμφωνημένη χειροκίνητη ανάθεση με περιορισμένη πρόσβαση και ελάχιστα δεδομένα. Επιβεβαιώστε πραγματική κατάσταση πληρωμών και κρατήσεων πριν από υποβολή· μην επινοείτε αποτέλεσμα παρόχου. Συντονιστείτε με υποστήριξη και καταγράψτε χειροκίνητες ενέργειες για συμφωνία.</p><h2 id="επαναφορα-και-επανεναρξη" tabindex="-1">Επαναφορά και επανέναρξη <a class="header-anchor" href="#επαναφορα-και-επανεναρξη" aria-label="Permalink to &quot;Επαναφορά και επανέναρξη&quot;">​</a></h2><p>Μόνο εξουσιοδοτημένο τεχνικό προσωπικό επαναφέρει επηρεαζόμενο περιβάλλον. Δοκιμάστε πρώτα σε απομόνωση, ελέγξτε συμβατότητα σχήματος και έκδοσης, εταιρικά όρια, λογαριασμούς, κρατήσεις/αναθέσεις, οικονομικό καθολικό και περιεχόμενο. Ελέγξτε χωριστά ενεργούς παρόχους. Μην αντιστρέφετε ανεξέλεγκτα migrations. Συμφωνήστε χαμένες ή διπλές ενέργειες, καταγράψτε τεκμήρια και λάβετε έγκριση πριν την επανέναρξη.</p><p>Δείτε <a href="/el/installation/">Εγκατάσταση</a>, <a href="/el/plus/software-update-manager.html">Ενημερώσεις</a>, <a href="/el/tutorials/payment-review.html">Έλεγχος πληρωμής</a> και <a href="/el/security-privacy/">Ασφάλεια</a>.</p>',11)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
